"""Run preparation twice and record whether every generated byte is reproducible."""

from __future__ import annotations

import argparse
import hashlib
import json
import subprocess
import sys
from pathlib import Path


PROJECT_ROOT = Path(__file__).resolve().parents[1]
PREPARE_SCRIPT = PROJECT_ROOT / "scripts" / "prepare_mealrecplus.py"
DEFAULT_MANIFEST = (
    PROJECT_ROOT / "results" / "data_preparation" / "mealrecplus_h_manifest.json"
)
DEFAULT_OUTPUT = (
    PROJECT_ROOT / "results" / "data_preparation" / "reproducibility_check.json"
)


def sha256_bytes(payload: bytes) -> str:
    """Return the SHA-256 digest of an in-memory payload."""
    return hashlib.sha256(payload).hexdigest()


def run_preparation() -> tuple[bytes, dict[str, object]]:
    """Execute the production preparation command and load its evidence."""
    subprocess.run([sys.executable, str(PREPARE_SCRIPT)], cwd=PROJECT_ROOT, check=True)
    payload = DEFAULT_MANIFEST.read_bytes()
    return payload, json.loads(payload)


def main() -> None:
    """Verify identical manifests and output hashes across two complete runs."""
    parser = argparse.ArgumentParser()
    parser.add_argument("--output", type=Path, default=DEFAULT_OUTPUT)
    args = parser.parse_args()

    first_bytes, first = run_preparation()
    second_bytes, second = run_preparation()
    manifests_identical = first_bytes == second_bytes
    outputs_identical = first["outputs"] == second["outputs"]
    if not manifests_identical or not outputs_identical:
        raise ValueError("Preparation is not deterministic across repeated runs")

    result = {
        "check_schema_version": 1,
        "runs": 2,
        "manifest_sha256_run_1": sha256_bytes(first_bytes),
        "manifest_sha256_run_2": sha256_bytes(second_bytes),
        "manifests_byte_identical": manifests_identical,
        "output_artifact_hashes_identical": outputs_identical,
        "output_artifacts_compared": len(first["outputs"]),
    }
    args.output.parent.mkdir(parents=True, exist_ok=True)
    args.output.write_text(
        json.dumps(result, indent=2, sort_keys=True) + "\n", encoding="utf-8", newline="\n"
    )
    print(json.dumps(result, indent=2))


if __name__ == "__main__":
    main()
